/** Msg defines the Msg service. */
export interface Msg {
  /**
   * UpdateParams defines a (governance) operation for updating the module
   * parameters. The authority defaults to the x/gov module account.
   */
  UpdateParams(request: MsgUpdateParams): Promise<MsgUpdateParamsResponse>;
  /**
   * CreatePool opens a new ERTH<->token pool. Permissionless, but refused until
   * the genesis liquidity auction has settled: the auction must be able to claim
   * its bid denom, and one pool per spoke token plus no way to delete a pool
   * means a dust pool created beforehand would block it permanently. The lock
   * lifts itself at settlement.
   */
  CreatePool(request: MsgCreatePool): Promise<MsgCreatePoolResponse>;
  /** AddLiquidity defines the AddLiquidity RPC. */
  AddLiquidity(request: MsgAddLiquidity): Promise<MsgAddLiquidityResponse>;
  /**
   * RemoveLiquidity begins a liquidity withdrawal. It does not pay out: the
   * shares are escrowed for the unbonding period and then swept to the
   * provider's wallet automatically, with no second transaction.
   */
  RemoveLiquidity(request: MsgRemoveLiquidity): Promise<MsgRemoveLiquidityResponse>;
  /** Swap defines the Swap RPC. */
  Swap(request: MsgSwap): Promise<MsgSwapResponse>;
  /**
   * StartLiquidityAuction opens the bidding window for the pre-funded genesis
   * liquidity auction. Governance-only, and only meaningful once IBC is live
   * and the intended bid asset actually exists on the chain.
   */
  StartLiquidityAuction(request: MsgStartLiquidityAuction): Promise<MsgStartLiquidityAuctionResponse>;
  /** BidLiquidityAuction contributes bid_denom to the open auction. */
  BidLiquidityAuction(request: MsgBidLiquidityAuction): Promise<MsgBidLiquidityAuctionResponse>;
  /** ClaimLiquidityAuction pays out a bidder's pro-rata ERTH after settlement. */
  ClaimLiquidityAuction(request: MsgClaimLiquidityAuction): Promise<MsgClaimLiquidityAuctionResponse>;
  /**
   * NoteSwap swaps a shielded note's value through any pool and mints the
   * output as a note. Unsigned private msg; see MsgNoteSwap.
   */
  NoteSwap(request: MsgNoteSwap): Promise<MsgNoteSwapResponse>;
  /**
   * BuyAnml swaps a transparent account's coins for ANML, minted as a note:
   * the way into ANML for an ERTH holder (ANML never sits in an account).
   */
  BuyAnml(request: MsgBuyAnml): Promise<MsgBuyAnmlResponse>;
  /**
   * AddLiquidityShielded deposits both legs from shielded notes (one bundle
   * releasing the pool token and ERTH) and mints the LP shares as a note.
   * Unsigned private msg; the only way to add to the ANML/ERTH pool.
   */
  AddLiquidityShielded(request: MsgAddLiquidityShielded): Promise<MsgAddLiquidityShieldedResponse>;
  /**
   * RemoveLiquidityShielded withdraws LP shares held as notes: both legs are
   * minted as notes when the unbonding matures. Unsigned private msg.
   */
  RemoveLiquidityShielded(request: MsgRemoveLiquidityShielded): Promise<MsgRemoveLiquidityShieldedResponse>;
}

